import React,{useEffect,useState} from 'react';
import {Plus,Save,Maximize2,Trash2,BookOpen} from 'lucide-react';
import {clone,activation,setActivation} from '../host/model';
import type {Data} from '../host/types';
import type {HostAdapter} from '../host/adapter';
import {useHost,useTask,SearchBox,Notice,Empty,Field,IconButton,NativeLink} from '../ui/common';
export default function World({host,deep,onDeep,initial}:{host:HostAdapter,deep?:boolean,onDeep?:()=>void,initial?:string}){
 const snap=useHost(host),task=useTask();
 const [name,setName]=useState(initial||snap.current.world||snap.resources.world[0]?.id||'');
 const [base,setBase]=useState<Data|null>(null),[draft,setDraft]=useState<Data|null>(null),[entry,setEntry]=useState(''),[query,setQuery]=useState(''),[bookQuery,setBookQuery]=useState(''),[tab,setTab]=useState('content'),[json,setJson]=useState(''),[saved,setSaved]=useState('');
 const dirty=Boolean(base&&draft&&JSON.stringify(base)!==JSON.stringify(draft))||tab==='json'&&Boolean(draft)&&json!==JSON.stringify(draft,null,2);
 useEffect(()=>{const unload=(e:BeforeUnloadEvent)=>{if(dirty){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',unload);return()=>window.removeEventListener('beforeunload',unload);},[dirty]);
 useEffect(()=>{let live=true;setBase(null);setDraft(null);setSaved('');if(name)host.readBook(name).then(data=>{if(live){setBase(clone(data));setDraft(clone(data));setEntry(Object.keys(data.entries??{})[0]??'');setJson(JSON.stringify(data,null,2));}}).catch(e=>{if(live)task.setError(e.message);});return()=>{live=false;};},[name]);
 // Before a containing dialog or panel closes, the shell consults this guard.
 useEffect(()=>{const guard=(e:Event)=>{if(dirty&&!confirm('世界书有未保存修改，放弃这些修改？'))e.preventDefault();};window.addEventListener('wb-before-close',guard);return()=>window.removeEventListener('wb-before-close',guard);},[dirty]);
 const choose=(next:string)=>{if(next===name)return;if(dirty&&!confirm('切换世界书将放弃未保存修改，继续？'))return;setTab('content');setName(next);};
 const update=(patch:Data)=>{if(!draft||!draft.entries[entry])return;const next=clone(draft);Object.assign(next.entries[entry],patch);setDraft(next);setSaved('');};
 const save=()=>task.run(async()=>{if(!base||!draft)return;const candidate=tab==='json'?JSON.parse(json):draft;const result=await host.saveBook(name,base,candidate);setBase(clone(result));setDraft(clone(result));setJson(JSON.stringify(result,null,2));setSaved('已保存');});
 const modeChange=(id:string,mode:string)=>{if(!draft)return;const next=clone(draft);next.entries[id]=setActivation(next.entries[id],mode);setDraft(next);setSaved('');};
 const entries=draft?Object.entries(draft.entries) as [string,Data][]:[];const selected=draft?.entries[entry];
 return <div className={`wb-world ${deep?'is-deep':''}`}>
  <div className="wb-world-tools"><BookOpen size={18}/><strong>世界书</strong><span className="wb-grow"/>{dirty&&<small>未保存</small>}<button onClick={save} disabled={!dirty||task.busy}><Save size={15}/>保存</button>{onDeep&&<IconButton title="深度编辑" onClick={onDeep}><Maximize2 size={17}/></IconButton>}</div>
  <Notice error={task.error}/>{saved&&<div className="wb-success" role="status">{saved}</div>}
  <div className="wb-world-grid">
   <section className="wb-book-column"><SearchBox value={bookQuery} onChange={setBookQuery} placeholder="搜索世界书"/><p className="wb-caption">全局启用 · 可多选</p>{snap.resources.world.filter(x=>x.name.toLowerCase().includes(bookQuery.toLowerCase())).map(book=><div key={book.id} className={`wb-book-row ${name===book.id?'is-active':''}`}><input type="checkbox" aria-label={`启用世界书 ${book.name}`} checked={book.active} onChange={e=>task.run(()=>host.toggleBook(book.id,e.target.checked))}/><button onClick={()=>choose(book.id)}>{book.name}</button></div>)}<NativeLink onClick={()=>host.native('world')}>新建 / 导入与绑定</NativeLink></section>
   <section className="wb-entry-column"><div className="wb-flex"><SearchBox value={query} onChange={setQuery} placeholder="搜索条目"/>{deep&&<IconButton title="新增条目" onClick={()=>task.run(async()=>{if(!draft)return;const next=clone(draft),item=await host.createEntry(name,next);setDraft(next);setEntry(String(item.uid));})}><Plus size={17}/></IconButton>}</div>{entries.filter(([,e])=>`${e.comment} ${e.key?.join(' ')}`.toLowerCase().includes(query.toLowerCase())).map(([id,e])=><div key={id} className={`wb-entry-row ${entry===id?'is-active':''} ${e.disable?'is-disabled':''}`}>
    <select aria-label={`${e.comment||id} 激活方式`} title="关键词 / 常驻 / 向量化" className={`wb-mode ${activation(e)}`} value={activation(e)} onChange={v=>modeChange(id,v.target.value)}><option value="keyword">● 关键词</option><option value="constant">● 常驻</option><option value="vector">↗ 向量化</option></select><button className="wb-row-main" onClick={()=>{setEntry(id);}}><strong>{e.comment||`条目 ${id}`}</strong><small>{e.constant?'始终参与':e.key?.join(' · ')||'无关键词'}</small></button><input type="checkbox" aria-label={`启用条目 ${e.comment||id}`} checked={!e.disable} onChange={v=>{const next=clone(draft!);next.entries[id].disable=!v.target.checked;setDraft(next);}}/></div>)}{!entries.length&&<Empty>选择世界书，开始整理条目</Empty>}</section>
   <section className="wb-entry-editor">{selected?<><div className="wb-editor-heading"><input aria-label="条目名称" value={selected.comment??''} onChange={e=>update({comment:e.target.value})}/>{deep&&<IconButton title="删除条目" onClick={()=>{if(confirm('删除此条目？保存后生效。')){const next=clone(draft!);delete next.entries[entry];setDraft(next);setEntry(Object.keys(next.entries)[0]??'');}}}><Trash2 size={16}/></IconButton>}</div><div className="wb-tabs">{(deep?['content','trigger','json']:['content','trigger']).map(t=><button key={t} className={tab===t?'is-active':''} onClick={()=>{if(tab==='json'){try{const data=JSON.parse(json);setDraft(data);}catch{task.setError('JSON 无法解析，请先修正。');return;}}if(t==='json')setJson(JSON.stringify(draft,null,2));setTab(t);}}>{t==='content'?'正文':t==='trigger'?'触发条件':'完整 JSON'}</button>)}</div>
   {tab==='content'?<textarea className="wb-content-editor" aria-label="世界书正文" value={selected.content??''} onChange={e=>update({content:e.target.value})}/>:tab==='json'?<textarea className="wb-content-editor wb-code" aria-label="世界书 JSON" value={json} onChange={e=>setJson(e.target.value)}/>:<div className="wb-fields"><Field label="激活方式"><select value={activation(selected)} onChange={e=>modeChange(entry,e.target.value)}><option value="keyword">关键词</option><option value="constant">常驻</option><option value="vector">向量化</option></select></Field><Field label="关键词（每行一个，支持正则）"><textarea value={(selected.key??[]).join('\n')} onChange={e=>update({key:e.target.value.split('\n').filter(Boolean)})}/></Field><Field label="辅助关键词（每行一个）"><textarea value={(selected.keysecondary??[]).join('\n')} onChange={e=>update({keysecondary:e.target.value.split('\n').filter(Boolean)})}/></Field><label><input type="checkbox" checked={!!selected.selective} onChange={e=>update({selective:e.target.checked})}/>使用辅助关键词</label></div>}</>:<Empty>选择一个条目</Empty>}</section>
   {deep&&selected&&<aside className="wb-parameters"><span className="wb-eyebrow">注入参数</span><Field label="注入位置"><select value={selected.position??0} onChange={e=>update({position:Number(e.target.value)})}>{['角色定义之前','角色定义之后','作者注释之前','作者注释之后','指定深度','示例之前','示例之后','Outlet'].map((v,i)=><option key={v} value={i}>{v}</option>)}</select></Field>{[['order','顺序'],['depth','深度'],['probability','概率 %']].map(([key,label])=><Field label={label} key={key}><input type="number" min={0} max={key==='probability'?100:undefined} value={selected[key]??0} onChange={e=>update({[key]:Number(e.target.value)})}/></Field>)}<label><input type="checkbox" checked={!!selected.useProbability} onChange={e=>update({useProbability:e.target.checked})}/>启用概率</label><NativeLink onClick={()=>host.native('world')}/><small>更多参数可在完整 JSON 或原生编辑器中调整。</small></aside>}
  </div><footer className="wb-legend"><span className="green">● 关键词</span><span className="blue">● 常驻</span><span className="purple">↗ 向量化</span><span className="wb-grow"/><small>角色 / 聊天绑定沿用原生设置</small></footer>
 </div>;
}
